import type { Metadata } from 'next';
import { asset } from './base';

/**
 * Title, description and social cards for a page. Images are generated by `pnpm og`
 * (scripts/og.mjs) into public/og/<slug>.png.
 */
export function pageMeta(slug: string, title: string, description: string): Metadata {
  const image = { url: asset(`/og/${slug}.png`), width: 1200, height: 630, alt: `${title} · Funnest Charts` };
  return {
    title,
    description,
    openGraph: { title: `${title} · Funnest Charts`, description, images: [image], siteName: 'Funnest Charts', locale: 'ko_KR', type: 'article' },
    twitter: { card: 'summary_large_image', title: `${title} · Funnest Charts`, description, images: [image.url] },
  };
}
